interface HowlandRequest {
  semanticModel: SemanticModel;
  targetLanguage: string;
  options?: TransformOptions;
}

interface HowlandResponse {
  targetCode: string;
  confidence: number;
  warnings: Warning[];
  metadata: TransformMetadata;
}

class HowlandClient {
  private apiUrl: string;
  private apiKey: string;

  constructor(config: HowlandConfig) {
    this.apiUrl = config.apiUrl;
    this.apiKey = config.apiKey;
  }

  async transform(request: HowlandRequest): Promise<HowlandResponse> {
    const response = await fetch(`${this.apiUrl}/transform`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.apiKey}`,
        'X-Model-Version': '2.0'
      },
      body: JSON.stringify({
        model: request.semanticModel,
        target: request.targetLanguage,
        options: {
          preserveComments: true,
          optimizeOutput: true,
          targetVersion: 'latest',
          ...request.options
        }
      })
    });

    if (!response.ok) {
      throw new HowlandError(
        `Transformation failed: ${response.statusText}`,
        response.status
      );
    }

    const result = await response.json();
    return this.validateResponse(result);
  }

  private validateResponse(response: any): HowlandResponse {
    if (!response.targetCode || response.confidence < 0.5) {
      throw new HowlandError(
        'Low confidence transformation',
        400,
        response
      );
    }

    return response;
  }
}

import { SemanticModel, Symbol, Type, Pattern } from './types';

class SemanticModelBuilder {
  private symbols: Map<string, Symbol>;
  private types: Map<string, Type>;
  private patterns: Pattern[];

  constructor() {
    this.symbols = new Map();
    this.types = new Map();
    this.patterns = [];
  }

  build(ast: AST): SemanticModel {
    this.extractSymbols(ast);
    this.inferTypes(ast);
    this.detectPatterns(ast);
    this.buildControlFlow(ast);

    return {
      language: ast.metadata.language,
      version: ast.metadata.version,
      symbols: Array.from(this.symbols.values()),
      types: Array.from(this.types.values()),
      patterns: this.patterns,
      controlFlow: this.controlFlowGraph,
      dependencies: this.extractDependencies(ast)
    };
  }

  private inferTypes(ast: AST): void {
    for (const [name, symbol] of this.symbols) {
      if (symbol.kind === 'function') {
        const returnType = this.analyzeReturnType(symbol.node);
        const paramTypes = symbol.parameters.map(p => 
          this.inferParameterType(p)
        );

        this.types.set(name, {
          kind: 'function',
          parameters: paramTypes,
          returns: returnType,
          generic: this.detectGenerics(symbol.node)
        });
      } else if (symbol.kind === 'class') {
        const methods = this.extractMethods(symbol.node);
        const properties = this.extractProperties(symbol.node);

        this.types.set(name, {
          kind: 'class',
          methods: methods.map(m => this.types.get(m.name)),
          properties: properties.map(p => ({
            name: p.name,
            type: this.inferPropertyType(p)
          })),
          inheritance: this.extractInheritance(symbol.node)
        });
      }
    }
  }

  private detectPatterns(ast: AST): void {
    const patterns = [
      new SingletonDetector(),
      new FactoryDetector(),
      new ObserverDetector(),
      new StrategyDetector()
    ];

    for (const detector of patterns) {
      const found = detector.detect(ast, this.symbols, this.types);
      if (found) {
        this.patterns.push(found);
      }
    }
  }
}
